async function toggleDrivingFullscreen(){
 const driving=$('driving');
 const status=$('mobileDisplayStatus');
 status.textContent='';
 if(document.fullscreenElement===driving){
  await leaveDrivingFullscreen();
  return;
 }
 try{
  await driving.requestFullscreen();
 }catch{
  status.textContent='Tela cheia indisponível aqui. Gire o celular para usar o painel horizontal.';
  return;
 }
 if(document.fullscreenElement!==driving)return;
 try{
  if(!screen.orientation?.lock)throw new Error('Rotação indisponível');
  await screen.orientation.lock('landscape');
 }catch{
  status.textContent='Gire o celular para usar o painel horizontal.';
 }
}

async function leaveDrivingFullscreen(){
 if(document.fullscreenElement!==$('driving'))return;
 try{await document.exitFullscreen()}catch{}
}

$('fullscreenGame').onclick=toggleDrivingFullscreen;
document.addEventListener('fullscreenchange',()=>{
 const fullscreen=document.fullscreenElement===$('driving');
 $('fullscreenGame').textContent=fullscreen?'Sair da tela cheia':'Tela cheia';
 $('mobileDisplayStatus').textContent='';
 (fullscreen?$('driving'):document.body).append($('toast'));
});
