let accounts;
let registering=false;
let recovering=false;

function authMessage(error){
 if(error?.code==='PGRST205')return 'A tabela de progresso ainda precisa ser criada no Supabase.';
 if(error?.code==='email_not_confirmed')return 'Confirme o cadastro no seu e-mail antes de entrar.';
 if(error?.code==='invalid_credentials')return 'Confira o e-mail e a senha.';
 if(error?.code==='weak_password')return 'Escolha uma senha mais forte.';
 return 'Falha ao acessar a conta. Confira a conexão e tente novamente.';
}

function save(){
 accounts.save(data).catch(error=>{
  toast(accounts.conflict?error.message:'Progresso pendente. Ao sair, o jogo tenta salvar novamente.');
 });
}

async function openAccount(user){
 data=await accounts.load(user,fresh);
 data.upgrades=data.upgrades||{};
 $('topuser').textContent=data.name.toUpperCase()+' • ONLINE';
 $('logout').classList.remove('hidden');
 show('home');
 GearLinePilots.start(accounts);
}

function authBusy(busy){
 $('enter').disabled=busy;
 $('authSwitch').disabled=busy;$('forgot').disabled=busy;
}

function setAuthMode(mode){
 registering=mode==='register';
 recovering=mode==='recover';
 const reset=mode==='reset';
 $('pilotField').classList.toggle('hidden',!registering);
 $('username').required=registering;
 $('authOptions').classList.toggle('hidden',registering||recovering||reset);
 $('passwordField').classList.toggle('hidden',recovering);
 $('password').disabled=recovering;
 $('password').required=!recovering;
 $('email').disabled=reset;
 $('forgot').classList.toggle('hidden',recovering||reset);
 $('authSwitch').classList.toggle('hidden',reset);
 $('enter').textContent=registering?'CRIAR CONTA':recovering?'ENVIAR LINK':reset?'SALVAR SENHA':'ENTRAR';
 $('authSwitch').textContent=registering||recovering?'VOLTAR AO LOGIN':'CRIAR CONTA';
 $('password').autocomplete=registering||reset?'new-password':'current-password';
 $('password').minLength=registering||reset?6:0;
 $('password').value='';
 $('autherr').textContent='';
}

$('authSwitch').onclick=()=>setAuthMode(registering||recovering?'login':'register');
$('forgot').onclick=()=>setAuthMode('recover');

$('authForm').onsubmit=async event=>{
 event.preventDefault();
 if(!accounts)return;
 authBusy(true);
 $('autherr').textContent='';
 const email=$('email').value.trim();
 const password=$('password').value;
 try{
  if(recovering){
   if(!email){$('autherr').textContent='Informe seu e-mail.';return}
   await accounts.resetPassword(email);
   $('autherr').textContent='';
   toast('Link de recuperação enviado. Confira seu e-mail.');
   setAuthMode('login');
   return;
  }
  if(accounts.recoveryPending()){
   if(password.length<6){$('autherr').textContent='Escolha uma senha com pelo menos 6 caracteres.';return}
   await accounts.updatePassword(password);
   accounts.clearRecovery();
   await openAccount(await accounts.restore());
   toast('Senha atualizada.');
   return;
  }
  const user=registering
   ?await accounts.register(email,password,$('username').value.trim())
   :await accounts.signIn(email,password,$('remember').checked);
  $('password').value='';
  if(user)await openAccount(user);
  else{
   setAuthMode('login');
   $('autherr').textContent='Confira seu e-mail para confirmar o cadastro e depois entre.';
  }
 }catch(error){
  $('autherr').textContent=authMessage(error);
 }finally{
  authBusy(false);
 }
};

$('logout').onclick=async()=>{
 if(GearLineCommunity.busy)return;
 $('logout').disabled=true;
 if(running&&!paused)$('pause').click();
 if(running&&mode==='free')saveFreeDrive();
 try{
  if(!accounts.conflict)await accounts.flush();
  await accounts.signOut();
   data=null;
  show('auth');
  $('logout').classList.add('hidden');
  $('topuser').textContent='CONTA ONLINE';
  $('password').value='';
 }catch{
  toast('O progresso ainda precisa ser salvo. Confira a conexão e tente sair de novo.');
 }finally{
  $('logout').disabled=false;
 }
};
