function ready(im){return im.complete&&im.naturalWidth>0}
const paintMaskImg=new Image();
paintMaskImg.src='data:image/png;base64,';
for(const image of [paintMaskImg,peugeot206Body,peugeot206Mask,peugeot206Wheels,astraBody,astraMask,astraFrontWheel,astraRearWheel,chevetteBody,chevetteMask,chevetteFrontWheel,chevetteRearWheel]){
 image.addEventListener('load',()=>{
  if(!$('garage').classList.contains('hidden'))drawCar();
 });
}

function bodyForColor(model,color=data[model.colorKey],paint=model.paint){
 const {body,mask}=model;
 if(!color||!colors[color]||!ready(mask))return body;
 if(paint.color===color)return paint.canvas;
 const width=body.naturalWidth,height=body.naturalHeight;
 const canvas=paint.canvas||document.createElement('canvas');
 canvas.width=width;
 canvas.height=height;
 const ctx=canvas.getContext('2d',{willReadFrequently:true});
 if(!paint.pixels){
  ctx.drawImage(mask,0,0);
  paint.pixels=ctx.getImageData(0,0,width,height).data;
  ctx.clearRect(0,0,width,height);
 }
 ctx.drawImage(body,0,0);
 const frame=ctx.getImageData(0,0,width,height);
 const [red,green,blue]=colors[color].slice(1).match(/../g).map(hex=>parseInt(hex,16));
 tintBodyPixels(frame.data,paint.pixels,red,green,blue);
 ctx.putImageData(frame,0,0);
 paint.color=color;
 paint.canvas=canvas;
 return canvas;
}

function tintBodyPixels(pixels,mask,red,green,blue){
 for(let i=0;i<pixels.length;i+=4){
  const amount=mask[i+3]/255;
  if(!amount||!pixels[i+3])continue;
  const light=.2126*pixels[i]+.7152*pixels[i+1]+.0722*pixels[i+2];
  const shade=light/210, highlight=Math.max(0,light-210)*.36;
  pixels[i]+=(Math.min(255,red*shade+highlight)-pixels[i])*amount;
  pixels[i+1]+=(Math.min(255,green*shade+highlight)-pixels[i+1])*amount;
  pixels[i+2]+=(Math.min(255,blue*shade+highlight)-pixels[i+2])*amount;
 }
}

function brakePressed(){return Boolean(keys.s||keys.arrowdown||touch.brake)}

function drawBrakeLight(x){
 const halo=x.createRadialGradient(1963,430,6,1963,430,74);
 halo.addColorStop(0,'rgba(255,42,26,.58)');
 halo.addColorStop(1,'rgba(255,21,12,0)');
 x.fillStyle=halo;
 x.fillRect(1889,356,148,148);

 const lens=x.createLinearGradient(0,408,0,450);
 lens.addColorStop(0,'#ff9881');
 lens.addColorStop(.35,'#ff392a');
 lens.addColorStop(1,'#d9120a');
 x.fillStyle=lens;
 x.beginPath();
 x.moveTo(1943,408);
 x.lineTo(1984,410);
 x.lineTo(1982,450);
 x.lineTo(1943,450);
 x.closePath();
 x.fill();
}

