const chevette={id:'chevette',name:'CHEVROLET CHEVETTE SL',shortName:'CHEVETTE SL',chip:'CHEVETTE 1.6',detail:'1.6 aspirado / tração traseira / 5 marchas',weight:'910 kg',traction:'Traseira',colorKey:'chevetteColor',power:75,...vehiclePhysics.chevette,body:chevetteBody,mask:chevetteMask,paint:{},width:1600,height:503,axleY:470,diameter:278,exhaustX:1480,exhaustY:456,brake:ctx=>drawNewBrakeLight(ctx,1568,321,8,14),wheels:preparedWheels(chevetteFrontWheel,chevetteRearWheel,[275,1260]),enginePitch:.84};
