function renderDealer(){
 $('dealerCash').textContent=displayCash();
 for(const [id,price] of Object.entries(dealerPrices)){
  const button=$('buy-'+id),owned=data.ownedVehicles.includes(id);
   button.disabled=owned||!newVehicleAvailable(id);
   button.textContent=owned?'Na garagem':newVehicleAvailable(id)?'Comprar por '+formatCash(price):'Em breve · '+formatCash(price);
 }
}

function buyVehicle(id){
 if(!data||!Object.hasOwn(dealerPrices,id)||data.ownedVehicles.includes(id)||!newVehicleAvailable(id))return;
 const price=dealerPrices[id];
 if(!accounts?.unlimitedCash&&data.cash<price){toast('Saldo insuficiente.');return;}
 if(!accounts?.unlimitedCash)data.cash-=price;
 data.ownedVehicles.push(id);
 data.vehicleId=id;
 save();
 show('garage');
 toast('Carro adicionado à garagem.');
}

for(const id of Object.keys(dealerPrices))$('buy-'+id).onclick=()=>buyVehicle(id);

function selectedVehicle(){return vehicles[data.vehicleId]||gol}

function bodyDrop(model){
 const {front,rear}=suspensionHeight();
 const [a,b]=model.wheels;
 return front+(rear-front)*(model.width/2-a.axle)/(b.axle-a.axle);
}
function bodyRake(model){
 const {front,rear}=suspensionHeight();
 return Math.atan2(rear-front,model.wheels[1].axle-model.wheels[0].axle);
}

function drawPeugeotBrakeLight(ctx){
 const glow=ctx.createRadialGradient(2024,365,4,2024,365,95);
 glow.addColorStop(0,'#ff361d88');
 glow.addColorStop(1,'#ff281700');
 ctx.fillStyle=glow;
 ctx.fillRect(1929,270,190,190);
 ctx.fillStyle='#ff452d';
 ctx.beginPath();
 ctx.ellipse(2024,365,35,11,.37,0,Math.PI*2);
 ctx.fill();
}

function drawNewBrakeLight(ctx,x,y,rx,ry){
 const glow=ctx.createRadialGradient(x,y,2,x,y,65);glow.addColorStop(0,'#ff361d88');glow.addColorStop(1,'#ff281700');
 ctx.fillStyle=glow;ctx.fillRect(x-65,y-65,130,130);
 ctx.fillStyle='#ff452d';ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();
}

function vehicle(ctx,cx,ground,width,angle,tilt,braking=false,remote=null){
 const model=remote?.model??selectedVehicle();
 const {body,axleY,diameter,wheels}=model;
 if(!ready(body)||!ready(wheels[0].image))return;
 const scale=width/model.width,center=model.width/2;
 ctx.save();
 ctx.translate(cx,ground);
 ctx.scale(-scale,scale);
 ctx.translate(-center,-(axleY+diameter/2));
 for(const wheel of wheels){
  const sprite=ready(wheel.image)?wheel:wheels[0];
  const scaleX=diameter/sprite.tireWidth,scaleY=diameter/sprite.tireHeight;
  ctx.save();
  ctx.translate(wheel.axle,axleY);
  ctx.rotate(-angle);
  if(sprite.source)ctx.drawImage(sprite.image,...sprite.source,-sprite.hubX*scaleX,-sprite.hubY*scaleY,diameter,diameter);
  else ctx.drawImage(sprite.image,-sprite.hubX*scaleX,-sprite.hubY*scaleY,
   sprite.image.naturalWidth*scaleX,sprite.image.naturalHeight*scaleY);
  ctx.restore();
 }
 ctx.save();
 ctx.translate(center,axleY+(remote?0:bodyDrop(model)));
 ctx.rotate(tilt+(remote?0:bodyRake(model)));
 ctx.translate(-center,-axleY);
 const sportExhaust=(remote?.upgrades??activeSetup().upgrades).exhaust;
 if(sportExhaust&&model.id!=='gol')drawPeugeotSportExhaust(ctx,model);
 ctx.drawImage(bodyForColor(model,remote?.color,remote?.paint),0,0,model.width,model.height);
 if(sportExhaust&&model.id==='gol')drawSportExhaust(ctx,model);
 if(braking)model.brake(ctx);
 ctx.restore();
 ctx.restore();
}
function drawPeugeotSportExhaust(ctx,model){
 ctx.save();
 ctx.translate(model.exhaustX,model.exhaustY);
 const metal=ctx.createLinearGradient(0,-7,0,7);
 metal.addColorStop(0,'#555b5e');
 metal.addColorStop(.43,'#c3c7c7');
 metal.addColorStop(1,'#3a3e40');
 ctx.fillStyle=metal;
 ctx.beginPath();
 ctx.roundRect(-25,-7,30,14,4);
 ctx.fill();
 ctx.fillStyle='#202426';
 ctx.beginPath();
 ctx.ellipse(0,0,4,5,0,0,Math.PI*2);
 ctx.fill();
 ctx.restore();
}

function drawSportExhaust(ctx,model){
 ctx.save();
 ctx.translate(model.exhaustX-1940,model.exhaustY-641);
 const metal=ctx.createLinearGradient(0,632,0,651);
 metal.addColorStop(0,'#4b5153');
 metal.addColorStop(.45,'#c3c7c7');
 metal.addColorStop(1,'#45494b');
 ctx.fillStyle=metal;
 ctx.beginPath();
 ctx.roundRect(1917,632,35,19,4);
 ctx.fill();
 ctx.fillStyle='#222729';
 ctx.beginPath();
 ctx.ellipse(1949,641.5,5,6.5,0,0,Math.PI*2);
 ctx.fill();
 ctx.restore();
}

function resizeDrawingBuffer(canvas,width,height,displayScale,maxPixels=2400000){
 const density=Math.min(window.devicePixelRatio||1,2);
 const budgetScale=Math.sqrt(maxPixels/(width*height));
 const scale=Math.min(budgetScale,Math.max(1,displayScale*density));
 const pixelWidth=Math.round(width*scale),pixelHeight=Math.round(height*scale);
 if(canvas.width!==pixelWidth)canvas.width=pixelWidth;
 if(canvas.height!==pixelHeight)canvas.height=pixelHeight;
}

function drawingContext(canvas,width,height){
 const ctx=canvas.getContext('2d');
 ctx.setTransform(canvas.width/width,0,0,canvas.height/height,0,0);
 ctx.imageSmoothingQuality='high';
 return ctx;
}

