const golEngineSamples=[
 {rpm:900,wav:''},
 {rpm:3600,wav:''},
 {rpm:6300,wav:''}
];

async function loadEngineSamples(context,engine,clips){
 try{
  const buffers=await Promise.all(clips.map(({wav})=>{
   const bytes=Uint8Array.from(atob(wav),character=>character.charCodeAt(0));
   return context.decodeAudioData(bytes.buffer);
  }));
  if(engine.disposed)return;
  engine.samples=buffers.map((buffer,index)=>{
   const source=context.createBufferSource();
   const gain=context.createGain();
   source.buffer=buffer;
   source.loop=true;
   gain.gain.value=0;
   source.connect(gain).connect(engine.filter);
   source.start();
   return {rpm:clips[index].rpm,source,gain};
  });
 }catch{
  // Keep the synthesized motor if the samples cannot load.
 }
}

function mixEngine(samples,rpm,speed,throttle,active,now,isGol){
 const highIndex=samples.findIndex(sample=>sample.rpm>=rpm);
 const upper=highIndex<0?samples.length-1:highIndex;
 const lower=highIndex<0?upper:Math.max(0,upper-1);
 const lateHighBlend=!isGol&&upper===samples.length-1;
 const blendStart=lateHighBlend?Math.max(samples[lower].rpm,6650):samples[lower].rpm;
 const blendEnd=lateHighBlend?7000:samples[upper].rpm;
 const blend=lower===upper?(lateHighBlend?Math.max(0,Math.min(1,(rpm-6650)/350)):0)
  :Math.max(0,Math.min(1,(rpm-blendStart)/(blendEnd-blendStart)));
 const lowSample=lateHighBlend?Math.max(0,upper-1):lower;
 const coastingVolume=.22+.12*Math.min(1,Math.max(0,speed)/5);
 const volume=active?(throttle?.64:coastingVolume):0;
 samples.forEach(({rpm:anchor,source,gain},index)=>{
  const weight=index===lowSample?1-blend:index===upper?blend:0;
  const idleLift=isGol&&index===0?1+.08*Math.max(0,1-(rpm-900)/900):1;
  source.playbackRate.setTargetAtTime(Math.max(.8,Math.min(!isGol&&index===samples.length-2?1.85:1.24,rpm/anchor*idleLift)),now,.09);
  gain.gain.setTargetAtTime(volume*weight,now,.1);
 });
}

async function loadNewEngineSamples(context,engine,clips){
 try{
  const decode=async wav=>context.decodeAudioData(Uint8Array.from(atob(wav),c=>c.charCodeAt(0)).buffer);
  const buffers=await Promise.all(clips.map(async clip=>({rpm:clip.rpm,off:await decode(clip.off),on:await decode(clip.on)})));
  if(engine.disposed)return;
  const layer=buffer=>{
   const source=context.createBufferSource(),gain=context.createGain();
   source.buffer=buffer;source.loop=true;gain.gain.value=0;
   source.connect(gain).connect(engine.filter);source.start();
   return {source,gain};
  };
  engine.newSamples=buffers.map(({rpm,off,on})=>({rpm,off:layer(off),on:layer(on)}));
 }catch{engine.samplesFailed=true;}
}

function mixNewEngine(samples,rpm,throttle,active,now){
 const firstHigher=samples.findIndex(sample=>sample.rpm>=rpm);
 const upper=firstHigher<0?samples.length-1:firstHigher;
 const lower=firstHigher<0?upper:Math.max(0,upper-1);
 const t=upper===lower?0:Math.max(0,Math.min(1,(rpm-samples[lower].rpm)/(samples[upper].rpm-samples[lower].rpm)));
 const blend=t*t*(3-2*t),load=throttle?.92:.08;
 const volume=active?(throttle?.86:.58):0;
 samples.forEach((sample,index)=>{
  const weight=lower===upper?(index===lower?1:0):index===lower?Math.sqrt(1-blend):index===upper?Math.sqrt(blend):0;
  const rate=Math.max(.62,Math.min(1.85,rpm/sample.rpm));
  for(const [name,amount] of [['off',Math.sqrt(1-load)],['on',Math.sqrt(load)]]){
   sample[name].source.playbackRate.setTargetAtTime(rate,now,.075);
   sample[name].gain.gain.setTargetAtTime(volume*weight*amount,now,.09);
  }
 });
}

const engineAudioByModel=new Map();
const touchDisplay=window.matchMedia('(pointer:coarse)');
const mobileOnlineUpdateMs=32;
let rivalAudio=null;
let rivalEffectBuffers=null;
const turboReleaseAudio=new Audio('data:audio/wav;base64,');
turboReleaseAudio.preload='auto';
let turboWasAccelerating=false;
let lastTurboRelease=-Infinity;

function playTurboRelease(){
 if(!running||paused||!activeSetup().upgrades.turbo||car.boost<.25)return;
 const now=performance.now();
 if(now-lastTurboRelease<220)return;
 lastTurboRelease=now;
 turboReleaseAudio.volume=.25+car.boost*.22;
 turboReleaseAudio.currentTime=0;
 turboReleaseAudio.play().catch(()=>{});
}
function playShiftSound(){
 try{shiftAudio.currentTime=0;shiftAudio.play().catch(()=>{})}catch(e){}
}
function resumeEngineAudio(){
 if(audio&&audio.state!=='running')audio.resume().catch(()=>{});
}
// A mobile browser may defer audio until a second genuine touch after fullscreen.
document.addEventListener('pointerup',()=>{if(running)resumeEngineAudio()},{capture:true,passive:true});
window.addEventListener('keydown',()=>{if(running)resumeEngineAudio()},{passive:true});
function createEngineAudio(model,output){
   const master=audio.createGain(); master.gain.value=.0001;
   const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=520;filter.Q.value=.65;
   filter.connect(master);master.connect(output);
   const synthGain=audio.createGain();
   synthGain.gain.value=0;
   synthGain.connect(filter);
   const voices=[];
   [1,2,3,4].forEach((harmonic,i)=>{
    const osc=audio.createOscillator(),gain=audio.createGain();
    osc.type=i===0?'triangle':'sine';gain.gain.value=[.42,.18,.07,.025][i];
    osc.connect(gain).connect(synthGain);osc.start();voices.push(osc);
   });
   const engine={voices,master,filter,synthGain,enginePitch:model.enginePitch||1};
   if(model.turboAvailable){
    const whistle=audio.createOscillator(),whistleGain=audio.createGain();
    whistle.type='sine';
    whistleGain.gain.value=0;
    whistle.connect(whistleGain).connect(master);
    whistle.start();
    engine.turbo={whistle,whistleGain};
   }
   engine.isNew=Boolean(typeof GearLineNewEngineAudio!=='undefined'&&GearLineNewEngineAudio[model.id]);
   if(engine.isNew)loadNewEngineSamples(audio,engine,GearLineNewEngineAudio[model.id]);
   else if(model.id==='gol'||model.id==='peugeot206')loadEngineSamples(audio,engine,model.id==='gol'?golEngineSamples:peugeotEngineSamples);
   return engine;
}
function startAudio(){
 try{
  audio=audio||new (window.AudioContext||window.webkitAudioContext)();
  resumeEngineAudio();
  const model=selectedVehicle();
  engineOsc=engineAudioByModel.get(model.id);
  if(!engineOsc){
   engineOsc=createEngineAudio(model,audio.destination);
   engineAudioByModel.set(model.id,engineOsc);
  }
 }catch(e){}
}
function mixCarAudio(engine,driver,throttle,active,boost,backfirePlaying=false){
  const now=audio.currentTime;
  const rpm=active?driver.rpm:900;
  const fundamental=active?Math.max(25,rpm/30)*engine.enginePitch:25;
  engine.voices.forEach((voice,i)=>voice.frequency.setTargetAtTime(fundamental*(i+1),now,.09));
  const {samples,newSamples,turbo}=engine;
  if(samples)mixEngine(samples,rpm,active?driver.speed:0,throttle,active,now,!turbo);
  if(newSamples)mixNewEngine(newSamples,rpm,throttle,active,now);
  if(turbo){
   turbo.whistle.frequency.setTargetAtTime(540+boost*580,now,.08);
   turbo.whistleGain.gain.setTargetAtTime(boost*.025,now,.09);
  }
  const engineVolume=backfirePlaying?.65:1;
  engine.master.gain.setTargetAtTime(active?engineVolume:0,now,backfirePlaying?.012:.07);
  const fallbackVolume=engine.isNew?(throttle?.24:.14):(throttle?.055:.018);
  engine.synthGain.gain.setTargetAtTime(active&&!samples&&!newSamples?fallbackVolume:0,now,.12);
  const cutoff=newSamples?Math.min(5000,1950+rpm*.45):samples?Math.min(4100,1750+rpm*.37):active?Math.min(1250,360+rpm*.12):220;
  engine.filter.frequency.setTargetAtTime(cutoff,now,.12);
}
function engineSound(){
 if(engineOsc&&audio){
  const active=running&&!paused;
  const throttle=keys.w||keys.arrowup||touch.throttle;
  const boost=active&&activeSetup().upgrades.turbo?car.boost:0;
  if(engineOsc.turbo){
   if(active&&turboWasAccelerating&&!throttle)playTurboRelease();
   turboWasAccelerating=active&&Boolean(throttle);
  }
  mixCarAudio(engineOsc,car,throttle,active,boost,active&&exhaustEffects.playing);
  const {samples,newSamples}=engineOsc;
  $('driving').dataset.engineAudio=audio.state!=='running'?audio.state:newSamples?'engine-samples':samples?'samples':engineOsc.samplesFailed?'fallback':'synth';
 }
}

function updateRivalAudio(other,state,now){
 if(!audio)return;
 if(!rivalAudio){
  const volume=audio.createGain();
  volume.gain.value=0;
  const pan=audio.createStereoPanner?.();
  if(pan)volume.connect(pan).connect(audio.destination);
  else volume.connect(audio.destination);
  rivalAudio={volume,pan,engine:createEngineAudio(rival.model,volume),effects:new Set(),tick:-1};
  if(!rivalEffectBuffers){
   const decode=bytes=>audio.decodeAudioData(bytes);
   rivalEffectBuffers={};
   fetch(turboReleaseAudio.src).then(response=>response.arrayBuffer()).then(decode)
    .then(buffer=>{rivalEffectBuffers.turboTick=buffer}).catch(()=>{});
   decode(Uint8Array.from(atob(backfireClip),character=>character.charCodeAt(0)).buffer)
    .then(buffer=>{rivalEffectBuffers.popTick=buffer}).catch(()=>{});
  }
 }
 const voice=rivalAudio;
 const previousTick=voice.tick;
 if(state.tick!==previousTick){
  voice.tick=state.tick;
  voice.updatedAt=now;
 }
 const active=now-voice.updatedAt<500&&other.time===null&&state.phase!=='finished'&&!document.hidden;
 const gap=rival.dist-car.dist;
 const proximity=Math.max(0,1-Math.abs(gap)/55);
 if(!touchDisplay.matches||active!==voice.active||now-voice.mixedAt>=mobileOnlineUpdateMs){
  voice.active=active;
  voice.mixedAt=now;
  voice.volume.gain.setTargetAtTime(active?.5*proximity**2:0,audio.currentTime,.07);
  voice.pan?.pan.setTargetAtTime(Math.max(-.85,Math.min(.85,gap/24)),audio.currentTime,.08);
  const accelerating=other.throttle??(other.speed>0);
  mixCarAudio(voice.engine,rival,accelerating,active,active?rival.boost:0);
 }
 if(!active||!proximity||audio.state!=='running'||previousTick<0||state.tick===previousTick)return;
 for(const event of ['turboTick','popTick']){
  const eventTick=other[event],buffer=rivalEffectBuffers[event];
  if(!buffer||!Number.isInteger(eventTick)||eventTick<=previousTick||eventTick>state.tick||state.tick-eventTick>12)continue;
  const source=audio.createBufferSource(),gain=audio.createGain();
  source.buffer=buffer;
  gain.gain.value=event==='turboTick'?.68:1.1;
  source.connect(gain).connect(voice.volume);
  voice.effects.add(source);
  source.onended=()=>voice.effects.delete(source);
  source.start();
 }
}

function stopRivalAudio(){
 if(!rivalAudio)return;
 const {engine,volume,pan,effects}=rivalAudio;
 rivalAudio=null;
 engine.disposed=true;
 volume.disconnect();
 pan?.disconnect();
 for(const voice of engine.voices)voice.stop();
 engine.turbo?.whistle.stop();
 for(const sample of engine.samples??[])sample.source.stop();
 for(const sample of engine.newSamples??[]){sample.on.source.stop();sample.off.source.stop();}
 for(const source of effects)source.stop();
}
function beep(freq,dur){try{let o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.value=.04;o.connect(g).connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.stop(audio.currentTime+dur)}catch(e){}}
const exhaustEffects=createExhaustEffects();
let lastHudFrame=-Infinity;

function loop(t){
 if(!running)return;
 const dt=Math.min(.1,Math.max(0,(t-last)/1000));
 last=t;
 if(!paused){
  if(onlineRace)updateOnlineRace(dt,t);
  else update(dt,t);
  if(!running)return;
 }else exhaustEffects.suspend();
 drawRoad(t,paused?0:dt);
 if(!(onlineRace||freeConnection)||!touchDisplay.matches||t-lastHudFrame>=mobileOnlineUpdateMs){
  lastHudFrame=t;
  renderHud();
 }
 engineSound();
 raf=requestAnimationFrame(loop);
}
