const raceVisualSpeed=2;
const racePixelsPerMeter=22*raceVisualSpeed;
const rolloutPixelsPerMeter=32*raceVisualSpeed;
const raceCameraCenter=410;
const raceCarWidth=350;
const rivalCarScale=.92;
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
let raceCameraLead=0;

function raceScreenOffset(){
 const finishBlend=Math.max(0,Math.min(1,(raceDistance-car.dist)/40));
 return -raceCameraLead*finishBlend;
}

function raceCameraDistance(){
 return Math.min(car.dist,raceDistance);
}

function raceCarX(driver,width=raceCarWidth){
 const distanceBeforeFinish=Math.min(driver.dist,raceDistance)-raceCameraDistance();
 const distanceAfterFinish=Math.max(0,driver.dist-raceDistance);
 return raceCameraCenter+raceScreenOffset()+(raceCarWidth-width)/2
  +distanceBeforeFinish*racePixelsPerMeter+distanceAfterFinish*rolloutPixelsPerMeter;
}

function clearedCamera(driver,width){
 return driver.finishTime!==null && raceCarX(driver,width)-width/2>=roadWidth;
}
const rivalParts=[
 ['tune','Acerto'],['exhaust','Escape'],['shortGearing','Câmbio curto'],
 ['nitro','Nitro'],['turbo','Turbo']
];
const rivalPaceCache=new Map();

function estimatedRaceTime(model,upgrades){
 const key=raceDistance+':'+model.id+':'+rivalParts.map(([part])=>Number(Boolean(upgrades[part]))).join('');
 if(!rivalPaceCache.has(key)){
  const test={
   ...newRun(1),model,upgrades,reaction:.28,shiftDelay:.24,shiftLimit:.94,
   launchRpm:Math.min(3450,model.torquePeak*.76)
  };
  while(test.finishTime===null&&test.elapsed<35)stepRival(test,.02,raceDistance);
  rivalPaceCache.set(key,test.finishTime??35);
 }
 return rivalPaceCache.get(key);
}

function createRival(playerUpgrades,random=Math.random){
 const stockMatch=!rivalParts.some(([part])=>playerUpgrades[part]);
 let model=selectedVehicle();
 let upgrades={};
 if(stockMatch){
  const target=estimatedRaceTime(selectedVehicle(),{});
  const stockModels=Object.values(vehicles).filter(candidate=>Math.abs(estimatedRaceTime(candidate,{})-target)<=1.5);
  model=stockModels[Math.floor(random()*stockModels.length)]||model;
 }
 if(!stockMatch){
  const target=estimatedRaceTime(selectedVehicle(),playerUpgrades)+.15;
  const candidates=[];
  for(const candidateModel of Object.values(vehicles)){
   const parts=rivalParts.filter(([part])=>part!=='turbo'||candidateModel.turboAvailable);
   for(let mask=0;mask<2**parts.length;mask++){
    const setup=Object.fromEntries(parts.filter((_,index)=>mask&(1<<index)).map(([part])=>[part,true]));
    const gap=Math.abs(estimatedRaceTime(candidateModel,setup)-target);
    candidates.push({model:candidateModel,upgrades:setup,gap});
   }
  }
  candidates.sort((a,b)=>a.gap-b.gap);
  const close=candidates.filter(candidate=>candidate.gap<=candidates[0].gap+.55);
  ({model,upgrades}=close[Math.floor(random()*close.length)]);
 }
 const parts=rivalParts.filter(([part])=>upgrades[part]).map(([,label])=>label);
 const fullBuild=model.turboAvailable?5:4;
 const buildName=parts.length===fullBuild?'Preparação completa'
  :parts.length>=4?'Preparação avançada':parts.join(' + ')||'Original';
 return {
  ...newRun(1),model,upgrades,buildName,paint:{},
  color:1+Math.floor(random()*(colors.length-1)),wheelAngle:0,
  reaction:stockMatch?.36+random()*.22:.20+random()*.16,
  shiftDelay:stockMatch?.30+random()*.10:.20+random()*.08,
  shiftLimit:(stockMatch?.86:.92)+random()*.04,
  launchRpm:stockMatch?2300:Math.min(3450,model.torquePeak*.76)
 };
}
let rival=null;
let laneY=470,lateral=0;
let freeConnection=null;
let trafficHitAt=-Infinity;
const freeDriverPaint=new Map();
let freeDrivePaid=0,freeDriveSaved=0;
const freeDriveMetersPerReal=15;

function rewardFreeDrive(){
 const earned=Math.floor(car.dist/freeDriveMetersPerReal);
 const delta=earned-freeDrivePaid;
 if(delta<=0)return;
 data.cash+=delta;
 freeDrivePaid=earned;
 $('racemsg').textContent='Percurso: +'+formatCash(earned);
 if(freeDrivePaid-freeDriveSaved>=25)saveFreeDrive();
}

function saveFreeDrive(){
 if(freeDrivePaid===freeDriveSaved)return;
 save();
 freeDriveSaved=freeDrivePaid;
}

function update(dt,t){
 const model=selectedVehicle(),upgrades=activeSetup().upgrades;
 const accel=keys.w||keys.arrowup||touch.throttle, brake=brakePressed();
 if(mode==='race'&&countdown>0){countdown=Math.max(0,countdown-dt);if(accel&&car.gear>0&&!penalty){penalty=true;toast('Queima de largada! Vitória e prêmio invalidados.')}$('racemsg').textContent=penalty?'QUEIMOU!':countdown>0?String(Math.ceil(countdown)):'VAI!';car.rpm+=( (accel?3400:900)-car.rpm)*Math.min(1,dt*5);if(!countdown)beep(880,.15);return;}
 const previousSpeed=car.speed;
 const previousDistance=car.dist, previousLane=laneY;
 const meters=advanceCar(car,model,upgrades,accel,brake,keys.n||touch.nitro,dt,{finishDistance:mode==='race'?raceDistance:Infinity});
 if(mode==='free'){const steer=Number(!!(keys.d||keys.arrowright))-Number(!!(keys.a||keys.arrowleft));const target=steer*Math.min(105,car.speed*2.2);lateral+=(target-lateral)*Math.min(1,dt*5);laneY=Math.max(360,Math.min(580,laneY+lateral*dt));if((laneY<=360&&lateral<0)||(laneY>=580&&lateral>0))lateral=0;}
 if(freeConnection&&car.speed>15&&t-trafficHitAt>=650&&GearLineFreeOnline.hitsTraffic(
  freeConnection.position(previousDistance),freeConnection.position(car.dist),previousLane,laneY,(performance.timeOrigin+t)/1000,dt
 )){
  car.speed*=.76;
  trafficHitAt=t;
 }
 if(mode==='free')rewardFreeDrive();
 if(mode==='race'){
  const targetLead=reducedMotion.matches?0:Math.min(94,car.speed*.55);
  raceCameraLead+=(targetLead-raceCameraLead)*Math.min(1,dt*3.5);
  roadScroll=raceCameraDistance()*115-raceScreenOffset();
 }
 else roadScroll+=meters*115;
 wheelAngle=(wheelAngle+meters*(mode==='race'?raceVisualSpeed:1)/.29)%(Math.PI*2);
 const acceleration=dt>0?(car.speed-previousSpeed)/dt:0;
 const targetPitch=Math.max(-.014,Math.min(.014,acceleration*.00095));
 pitch+=(targetPitch-pitch)*Math.min(1,dt*7);
 if(mode==='race'){
  if(rival){
   const rivalMeters=stepRival(rival,dt,raceDistance)||0;
   rival.wheelAngle=(rival.wheelAngle+rivalMeters*raceVisualSpeed/.29)%(Math.PI*2);
  }
  if(clearedCamera(car,raceCarWidth)&&(!rival||clearedCamera(rival,raceCarWidth*rivalCarScale))){finishRace();return;}
  if(car.elapsed>1.5){
   $('racemsg').textContent=car.finishTime!==null?(rival&&rival.finishTime===null?'Aguardando rival':'Linha cruzada!')
    :rival&&rival.finishTime!==null?'Rival cruzou a linha'
    :Math.max(0,raceDistance-car.dist).toFixed(0)+' m restantes';
  }
 }
}

function renderRaceMap(){
 if(mode!=='race')return;
 const progress=distance=>100*Math.max(0,Math.min(1,distance/raceDistance));
 $('mapPlayer').style.left=progress(car.dist)+'%';
 if(rival)$('mapRival').style.left=progress(rival.dist)+'%';
}

function renderHud(){renderRaceMap();$('speed').textContent=Math.round(car.speed);$('rpmtext').textContent=Math.round(car.rpm)+' RPM';const maxRpm=selectedVehicle().maxRpm;$('rpmmax').textContent=maxRpm.toLocaleString('pt-BR');$('rpmfill').style.width=Math.min(100,car.rpm/maxRpm*100)+'%';$('gear').innerHTML=(car.gear||'N')+'<small>MARCHA</small>';const nitroActive=!paused&&car.finishTime===null&&car.nitroActive;const status=$('nitrostatus');status.textContent=activeSetup().upgrades.nitro?(nitroActive?'NITRO ATIVO: ':'NITRO: ')+Math.ceil(car.nitro)+'%':'NITRO: INDISPONÍVEL';$('driving').classList.toggle('nitro-active',!!nitroActive);$('throttle').classList.toggle('active',!!(keys.w||keys.arrowup||touch.throttle));$('brake').classList.toggle('active',brakePressed())}
const cleanAsphalt=new Image();cleanAsphalt.src="data:image/jpeg;base64,";
const wideTrack=window.matchMedia('(min-width:1180px) and (pointer:fine)');
const roadCanvas=$('road');
const roadHeight=600;
let roadWidth=1000;
function updateRoadResolution(width,height){
 if(width<=0||height<=0)return;
 roadWidth=(wideTrack.matches||window.matchMedia('(orientation:landscape) and (pointer:coarse)').matches)?Math.round(width*roadHeight/height):1000;
 const displayScale=Math.min(width/roadWidth,height/roadHeight);
 const maxPixels=(onlineRace||freeConnection)&&touchDisplay.matches?950000:undefined;
 resizeDrawingBuffer(roadCanvas,roadWidth,roadHeight,displayScale,maxPixels);
}
const roadViewport=new ResizeObserver(([{contentRect}])=>{
 updateRoadResolution(contentRect.width,contentRect.height);
});
roadViewport.observe(roadCanvas.parentElement);
window.addEventListener('resize',()=>{
 updateRoadResolution(roadCanvas.clientWidth,roadCanvas.clientHeight);
 if(garageCanvas.clientWidth>0)drawCar();
});

const grandstandImg=new Image();
grandstandImg.src='-Assets/Texture/arquibancada-v7.png';

function drawGrandstands(ctx,viewportWidth,scroll){
 if(!ready(grandstandImg))return;
 // Trim transparent margins in the source at draw time.
 const sourceY=286,sourceHeight=220;
 const height=148,baseY=246;
 const width=grandstandImg.naturalWidth*height/sourceHeight;
 const offset=((scroll*.42%width)+width)%width;
 for(let left=-offset;left<viewportWidth;left+=width){
  ctx.drawImage(grandstandImg,0,sourceY,grandstandImg.naturalWidth,sourceHeight,left,baseY-height,width,height);
 }
}

function drawRivalSpeedLines(ctx,center,width){
 if(reducedMotion.matches||rival.finishTime!==null||rival.speed<12)return;
 const intensity=Math.min(1,(rival.speed-12)/95);
 const rear=center-width*.43;
 ctx.save();
 ctx.strokeStyle='#cfdfed';
 ctx.globalAlpha=.32*intensity;
 ctx.lineWidth=1.5;
 ctx.beginPath();
 for(let i=0;i<9;i++){
  const phase=(i*27+rival.dist*16)%125;
  const x=rear-phase;
  const y=308+(i*31)%93;
  ctx.moveTo(x,y);
  ctx.lineTo(x-12-intensity*55,y);
 }
 ctx.stroke();
 ctx.restore();
}

function drawRaceSpeedLines(ctx,width){
 if(reducedMotion.matches||car.finishTime!==null||car.speed<40)return;
 const intensity=Math.min(1,(car.speed-40)/120);
 const span=width+320;
 ctx.save();
 ctx.strokeStyle='#c4d7e4';
 for(let layer=0;layer<2;layer++){
  const count=Math.ceil((layer===0?18:24)*width/1000);
  ctx.globalAlpha=intensity*(layer===0?.24:.42);
  ctx.lineWidth=layer===0?1.1:1.8;
  ctx.beginPath();
  for(let i=0;i<count;i++){
   const offset=i*173+layer*71-roadScroll*(layer===0?1.1:1.8);
   const x=((offset%span+span)%span)-250;
   const y=layer===0?295+(i*53)%115:466+(i*37)%120;
   ctx.moveTo(x,y);
   ctx.lineTo(x+24+intensity*(layer===0?108:190),y);
  }
  ctx.stroke();
 }
 ctx.restore();
}

function drawStartLights(ctx,center){
 const amberCount=Math.max(0,Math.min(3,4-Math.ceil(countdown)));
 ctx.save();
 const housing=ctx.createLinearGradient(0,106,0,164);
 housing.addColorStop(0,'#23313d');
 housing.addColorStop(.24,'#121d28');
 housing.addColorStop(1,'#080f17');
 ctx.beginPath();
 ctx.roundRect(center-106,107,212,58,16);
 ctx.fillStyle=housing;
 ctx.fill();
 ctx.strokeStyle='#435460';
 ctx.lineWidth=1.5;
 ctx.stroke();
 for(let i=0;i<4;i++){
  const color=i===3
   ?(penalty?'#ff504b':countdown<=0?'#77f783':null)
   :countdown>0&&i<amberCount?'#ffbd49':null;
  const x=center+(i-1.5)*49,y=136;
  ctx.beginPath();
  ctx.arc(x,y,17,0,Math.PI*2);
  ctx.fillStyle='#070c12';
  ctx.fill();
  ctx.strokeStyle=color||'#4b5d6d';
  ctx.stroke();
  const lens=ctx.createRadialGradient(x-4,y-5,1,x,y,14);
  lens.addColorStop(0,color?'#fff6d5':'#354655');
  lens.addColorStop(.48,color||'#21303c');
  lens.addColorStop(1,color||'#111b25');
  ctx.beginPath();
  ctx.arc(x,y,13,0,Math.PI*2);
  ctx.fillStyle=lens;
  if(color&&!reducedMotion.matches){ctx.shadowColor=color;ctx.shadowBlur=13;}
  ctx.fill();
  ctx.shadowBlur=0;
 }
 ctx.restore();
}


const dragAsphalt=new Image();
dragAsphalt.src='-Assets/Texture/asfalto-arrancada-com-chegada.png';

function drawDragAsphalt(ctx,width,top,height,finishX){
 const {naturalWidth:sourceWidth,naturalHeight:sourceHeight}=dragAsphalt;
 const scale=height/sourceHeight;
 // The two repeatable sections stop outside the painted checkerboard.
 const finishCenter=Math.round(sourceWidth*1354/2172);
 const beforeWidth=Math.floor(sourceWidth*.60);
 const afterStart=Math.ceil(sourceWidth*.65);
 const left=finishX-finishCenter*scale;
 const right=left+sourceWidth*scale;
 if(left<width&&right>0)ctx.drawImage(dragAsphalt,left,top,sourceWidth*scale,height);

 function extend(edge,sourceX,sampleWidth,direction){
  const tileWidth=sampleWidth*scale;
  const first=Math.max(0,Math.floor((direction<0?edge-width:-edge)/tileWidth));
  for(let index=first;;index++){
   const x=edge+(direction<0?-index-1:index)*tileWidth;
   if(direction<0?x+tileWidth<=0:x>=width)break;
   const mirrored=index%2===0;
   ctx.save();
   ctx.translate(x+(mirrored?tileWidth:0),top);
   if(mirrored)ctx.scale(-1,1);
   ctx.drawImage(dragAsphalt,sourceX,0,sampleWidth,sourceHeight,0,0,tileWidth,height);
   ctx.restore();
  }
 }
 extend(left,0,beforeWidth,-1);
 extend(right,afterStart,sourceWidth-afterStart,1);
}

function drawFallbackFinish(ctx,x,viewportWidth){
 if(x+6<=0||x-6>=viewportWidth)return;
 for(let row=0;row<24;row++){
  ctx.fillStyle=row%2?'#111':'#eee';ctx.fillRect(x-6,280+row*13,6,13);
  ctx.fillStyle=row%2?'#eee':'#111';ctx.fillRect(x,280+row*13,6,13);
 }
}

function drawDuskBackdrop(ctx,width){
 const sky=ctx.createLinearGradient(0,0,0,250);
 sky.addColorStop(0,'#263552');
 sky.addColorStop(.45,'#786382');
 sky.addColorStop(.82,'#e48e6c');
 sky.addColorStop(1,'#ffc088');
 ctx.fillStyle=sky;
 ctx.fillRect(0,0,width,285);

 const sunX=width*.77;
 const glow=ctx.createRadialGradient(sunX,138,15,sunX,138,105);
 glow.addColorStop(0,'#ffdc9ccc');
 glow.addColorStop(1,'#ffb37100');
 ctx.fillStyle=glow;
 ctx.fillRect(sunX-105,33,210,210);
 ctx.fillStyle='#ffe1aa';
 ctx.beginPath();
 ctx.arc(sunX,138,25,0,Math.PI*2);
 ctx.fill();

 const hills=[
  {base:190,amplitude:32,scroll:roadScroll*.018,color:'#57465d'},
  {base:222,amplitude:26,scroll:roadScroll*.04,color:'#322f43'}
 ];
 for(const {base,amplitude,scroll,color} of hills){
  ctx.fillStyle=color;
  ctx.beginPath();ctx.moveTo(0,285);
  for(let x=0;x<=width+12;x+=12){
   const phase=(x+scroll)/210;
   ctx.lineTo(x,base+amplitude*(Math.sin(phase)+.34*Math.sin(phase*2.7)));
  }
  ctx.lineTo(width,285);ctx.closePath();ctx.fill();
 }
}

function drawDistanceBoards(ctx,width,finishX){
 for(let distance=100;distance<=raceDistance;distance+=100){
  const x=finishX-(raceDistance-distance)*racePixelsPerMeter;
  if(x<-42||x>width+42)continue;
  ctx.fillStyle='#25313a';
  ctx.fillRect(x-2,202,4,35);
  ctx.fillStyle='#13232e';
  ctx.fillRect(x-32,180,64,26);
  ctx.strokeStyle='#f0c489';
  ctx.strokeRect(x-32,180,64,26);
  ctx.fillStyle='#ffe4b5';
  ctx.font='bold 13px Arial';
  ctx.textAlign='center';
  ctx.fillText(distance+' m',x,198);
 }
 ctx.textAlign='left';
}

function visibleFreeDrivers(width,center,t,dt){
 if(!freeConnection)return [];
 const avenue=GearLineFreeOnline;
 const origin=freeConnection.position(car.dist);
 const blend=Math.min(1,dt*14);
 const nearby=[];
 function place(peer,distance,lane){
  const model=vehicles[peer.vehicle];
  if(!model)return;
  const x=center+(distance-origin)*avenue.pixelsPerMeter;
  const size=avenue.carWidth(lane);
  if(x>=-size&&x<=width+size)nearby.push({peer,model,x,size,y:avenue.ground(lane)});
 }
 for(const peer of freeConnection.drivers.values()){
  const distance=avenue.currentDistance(peer,t);
  if(distance===null)continue;
  peer.shownDistance=Math.max(peer.shownDistance,peer.shownDistance+(distance-peer.shownDistance)*blend);
  peer.shownLane+=(peer.lane-peer.shownLane)*blend;
  peer.wheelAngle=(peer.wheelAngle+peer.speed/3.6*dt/.29)%(Math.PI*2);
  place(peer,peer.shownDistance,peer.shownLane);
 }
 for(const traffic of avenue.nearbyTraffic(origin,(performance.timeOrigin+t)/1000))place(traffic,traffic.distance,traffic.lane);
 return nearby.sort((a,b)=>a.y-b.y);
}

function drawFreeDriver(ctx,{peer,model,x,size,y}){
 const paintKey=model.id+':'+peer.color;
 if(!freeDriverPaint.has(paintKey))freeDriverPaint.set(paintKey,{});
 ctx.save();
 ctx.fillStyle='#080c10aa';
 ctx.beginPath();ctx.ellipse(x,y,size*.45,8,0,0,Math.PI*2);ctx.fill();
 vehicle(ctx,x,y,size,peer.wheelAngle,0,peer.braking,{model,color:peer.color,upgrades:{exhaust:peer.exhaust},paint:freeDriverPaint.get(paintKey)});
 ctx.restore();
}

function drawPilotTag(ctx,pilot,x,ground,width,model,viewportWidth){
 if(!pilot.name||x<0||x>viewportWidth)return;
 const y=ground-width*(model.axleY+model.diameter/2)/model.width-8;
 const level=Number.isInteger(pilot.level)&&pilot.level>0?' ['+pilot.level+']':'';
 const crew=pilot.crewTag?' · '+pilot.crewTag:'';
 const line=pilot.name+level+crew;
 ctx.save();
 ctx.font='800 14px Inter,Arial,sans-serif';
 const size=Math.min(198,Math.ceil(ctx.measureText(line).width));
 const center=Math.max(size/2+4,Math.min(viewportWidth-size/2-4,x));
 ctx.textAlign='center';
 ctx.lineJoin='round';
 ctx.lineWidth=3;
 ctx.strokeStyle='#0b1218';
 ctx.fillStyle='#c5f36b';
 ctx.strokeText(line,center,y,size);
 ctx.fillText(line,center,y,size);
 ctx.restore();
}

function drawRoad(t,dt){
 const w=roadWidth,h=roadHeight,x=drawingContext(roadCanvas,w,h);
 x.fillStyle='#101e2b';x.fillRect(0,0,w,h);
 const impactAge=t-trafficHitAt;
 if(freeConnection&&!paused&&!reducedMotion.matches&&impactAge<180){
  x.translate(0,Math.cos(impactAge*.085)*3.5*(1-impactAge/180));
 }
 function tile(im,y,hh,offset,ww){if(!ready(im))return;let start=-((offset%ww+ww)%ww);for(let i=start;i<w;i+=ww)x.drawImage(im,i,y,ww,hh)}
 const dusk=mode==='race'&&trackId==='dusk';
 if(freeConnection)GearLineFreeOnline.drawScenery(x,w,freeConnection.position(car.dist)*GearLineFreeOnline.pixelsPerMeter,cleanAsphalt);
 else if(dusk)drawDuskBackdrop(x,w);
 else if(ready(scene.forest)){const ww=1560,off=((roadScroll*.035)%(ww*2)+ww*2)%(ww*2);for(let i=-1;i<4;i++){let pos=i*ww-off; x.save();x.translate(pos+(i%2!==0?ww:0),0);x.scale(i%2!==0?-1:1,1);x.drawImage(scene.forest,0,0,ww,285);x.restore();}}
 if(mode==='race')drawGrandstands(x,w,roadScroll);
 const top=270, bottom=600;
 const hasDragAsphalt=mode==='race'&&ready(dragAsphalt);
 const finishX=mode==='race'?raceCameraCenter+raceScreenOffset()+raceCarWidth/2
  +(raceDistance-raceCameraDistance())*racePixelsPerMeter:0;
 if(!freeConnection){
 x.fillStyle='#292d30';x.fillRect(0,top,w,bottom-top);
 if(hasDragAsphalt)drawDragAsphalt(x,w,top,bottom-top,finishX);
 else if(ready(cleanAsphalt)){const size=330;for(let xx=-((roadScroll%size+size)%size);xx<w;xx+=size)x.drawImage(cleanAsphalt,xx,top,size,size);}
 x.fillStyle=dusk?'rgba(95,49,25,.15)':hasDragAsphalt?'rgba(0,0,0,.16)':'rgba(0,0,0,.35)';x.fillRect(0,top,w,bottom-top);
 tile(scene.barrier,220,60,roadScroll,255);
 if(dusk)drawDistanceBoards(x,w,finishX);
 if(!hasDragAsphalt){x.fillStyle='#a8a9a3';x.fillRect(0,top+10,w,2);x.fillRect(0,590,w,2);}
 if(mode==='free'){
  for(const yy of [380,490])for(let xx=-((roadScroll%150+150)%150);xx<w;xx+=150){x.fillStyle='#a5a6a1';x.fillRect(xx,yy,75,3)}
 }else if(!hasDragAsphalt){
  x.fillStyle='#b99a39';x.fillRect(0,430,w,11);
 }
 }
 const ground=freeConnection?GearLineFreeOnline.ground(laneY):mode==='free'?laneY:565;
 const width=freeConnection?GearLineFreeOnline.carWidth(laneY):mode==='free'?300+(laneY-360)*.18:raceCarWidth;
 const cx=mode==='race'?raceCarX(car):410;
 const freeDrivers=visibleFreeDrivers(w,cx,t,dt);
 if(mode==='race'&&!hasDragAsphalt)drawFallbackFinish(x,finishX,w);
 if(mode==='race')drawRaceSpeedLines(x,w);
 else if(car.speed>55){const strength=Math.min(.32,(car.speed-55)/400);x.save();x.globalAlpha=strength;x.strokeStyle='#c4d7e4';x.lineWidth=1.2;const span=w+200,count=Math.ceil(22*w/1000);for(let i=0;i<count;i++){let px=((i*173-roadScroll*1.3)%span+span)%span-100,py=100+(i*73)%480;x.beginPath();x.moveTo(px,py);x.lineTo(px+25+car.speed*.45,py);x.stroke()}x.restore();}
 for(const entry of freeDrivers)if(entry.y<ground)drawFreeDriver(x,entry);
 x.fillStyle='#080c10aa';x.beginPath();x.ellipse(cx,ground,width*.45,9,0,0,7);x.fill();
 if(rival){
  const rivalWidth=width*rivalCarScale;
  const rivalX=raceCarX(rival,rivalWidth);
  if(rivalX>-width/2&&rivalX<w+width/2){
   x.fillStyle='#080c10aa';x.beginPath();x.ellipse(rivalX,410,width*.42,8,0,0,Math.PI*2);x.fill();
   drawRivalSpeedLines(x,rivalX,rivalWidth);
   vehicle(x,rivalX,410,rivalWidth,rival.wheelAngle,0,false,rival);
   if(onlineRace)drawPilotTag(x,rival,rivalX,410,rivalWidth,rival.model,w);
   else{x.font='bold 13px Arial';x.textAlign='center';x.fillStyle='#f5eddb';x.fillText('RIVAL',rivalX,286);x.textAlign='left';}
  }
 }
 const tilt=pitch+(mode==='free'?lateral*.00045:0);
 const model=selectedVehicle();
 const bodyTilt=tilt+bodyRake(model);
 const scale=width/model.width,offsetX=model.exhaustX-model.width/2,offsetY=model.exhaustY-model.axleY;
 const tailpipe={
  x:cx-scale*(Math.cos(bodyTilt)*offsetX-Math.sin(bodyTilt)*offsetY),
  y:ground+scale*(Math.sin(bodyTilt)*offsetX+Math.cos(bodyTilt)*offsetY-model.diameter/2+bodyDrop(model)),
  angle:-bodyTilt,smokeRiseDelay:model.id!=='gol'?.18:0
 };
 const accelerating=Boolean(keys.w||keys.arrowup||touch.throttle);
 if(dt>0)exhaustEffects.update(dt,tailpipe,car.speed,accelerating,car.rpm,Boolean(activeSetup().upgrades.backfire)&&countdown<=0&&car.finishTime===null,audio);
 exhaustEffects.draw(x,tailpipe);
 vehicle(x,cx,ground,width,wheelAngle,tilt,!paused&&brakePressed());
 for(const entry of freeDrivers)if(entry.y>=ground)drawFreeDriver(x,entry);
 for(const entry of freeDrivers)drawPilotTag(x,entry.peer,entry.x,entry.y,entry.size,entry.model,w);
 if(mode==='race'){
 if(countdown>0||car.elapsed<1.2)drawStartLights(x,w/2);
 }
}
function shift(dir){
 if(!running||paused||car.finishTime!==null)return;
 if(onlineRace){onlineRace.shift(dir);return;}
 const next=Math.max(0,Math.min(5,car.gear+dir));
 if(next===car.gear)return;
 const model=selectedVehicle();
 if(dir<0&&car.speed*gearRatio(next,activeSetup().upgrades,model)*30>model.maxRpm-100){toast("Redução bloqueada: RPM alto.");return;}
 if(car.gear>0&&dir>0&&countdown<=0&&(keys.w||keys.arrowup||touch.throttle)){
  playTurboRelease();
  exhaustEffects.backfire(activeSetup().upgrades.backfire,car.rpm,audio);
 }
 car.shiftLock=car.gear===0?0:.22;
 car.gear=next;
 if(next===0)car.clutch=0;
 playShiftSound();
 renderHud();
}
function stopGame(){
 stopRivalAudio();
 if(freeConnection){
  freeConnection.close();
  freeConnection=null;
  freeDriverPaint.clear();
 }
 if(onlineRace){
  onlineRace.close(!onlineRace.state?.result);
  onlineRace=null;
 }
 if(running&&mode==='free')saveFreeDrive();
 running=false;
 turboWasAccelerating=false;
 turboReleaseAudio.pause();
 exhaustEffects.reset();
 if(raf)cancelAnimationFrame(raf);
 raf=0;
 keys={};
 touch={throttle:false,brake:false};
 if(engineOsc&&audio){
  try{engineOsc.master.gain.setTargetAtTime(0,audio.currentTime,.06)}catch(e){}
 }
}
function selectedRaceTrack(){
 return document.querySelector('[name=raceTrack]:checked')?.value==='dusk'?'dusk':'night';
}

function prepareOnlineRace(){
 if(!data?.vehicleId)throw new Error('GL_PROFILE_REQUIRED');
 if(['astra','chevette'].includes(data.vehicleId)&&!window.GEARLINE_NEW_CARS_ONLINE)throw new Error('GL_VEHICLE_ONLINE_PENDING');
 startAudio();
 return data[selectedVehicle().colorKey]??0;
}

function updateOnlineRace(dt,now){
 const connection=onlineRace;
 connection.poll(now,{
  throttle:Boolean(keys.w||keys.arrowup||touch.throttle),
  brake:brakePressed(),nitro:Boolean(keys.n||touch.nitro)
 });
 if(connection.failed){
  show('raceLobby');
  toast('Conexão com a corrida interrompida.');
  return;
 }
 const state=connection.sample(now);
 if(!state||state.phase==='waiting')return;
 const own=state.players.find(player=>player.id===connection.id);
 const other=state.players.find(player=>player.id!==connection.id);
 if(!rival){
  const model=vehicles[other.vehicleId]||gol;
  rival={...newRun(),model,upgrades:{exhaust:other.exhaust===true},buildName:'',color:other.color??0,paint:{},wheelAngle:0,
   name:other.name??'Rival',level:other.level,crewTag:other.crewTag};
  $('rivalchip').textContent='Rival: '+model.chip;
  $('rivalchip').classList.remove('hidden');
  $('mapRival').classList.remove('hidden');
  $('raceMap').setAttribute('aria-label','Mapa da arrancada. Jogador em verde, rival em azul.');
 }
 const follow=(driver,snapshot)=>{
  const previous=driver.dist;
  driver.dist=Math.max(driver.dist,driver.dist+(snapshot.distance-driver.dist)*Math.min(1,dt*20));
  driver.speed=snapshot.speed;
  driver.rpm=snapshot.rpm;
  driver.gear=snapshot.gear;
  driver.nitro=snapshot.nitro;
  driver.nitroActive=snapshot.nitroActive;
  driver.boost=snapshot.boost??0;
  driver.finishTime=snapshot.time;
  return (driver.dist-previous)*raceVisualSpeed/.29;
 };
 if(car.gear!==own.gear){
  if(car.gear>0&&own.gear>car.gear&&countdown<=0&&(keys.w||keys.arrowup||touch.throttle)){
   playTurboRelease();
   exhaustEffects.backfire(activeSetup().upgrades.backfire,car.rpm,audio);
  }
  playShiftSound();
 }
 wheelAngle=(wheelAngle+follow(car,own))%(Math.PI*2);
 rival.wheelAngle=(rival.wheelAngle+follow(rival,other))%(Math.PI*2);
 updateRivalAudio(other,state,now);
 countdown=Math.max(0,(state.startsAtTick-state.tick)*.02);
 car.elapsed=Math.max(0,(state.tick-state.startsAtTick)*.02);
 penalty=own.falseStart;
 roadScroll=raceCameraDistance()*115;
 $('racemsg').textContent=penalty?'QUEIMOU!':countdown>0?String(Math.ceil(countdown))
  :own.time!==null?'Linha cruzada!':car.elapsed<1.2?'VAI!':Math.ceil(raceDistance-own.distance)+' m restantes';
 if(state.phase==='finished')finishOnlineRace(state,own,other);
}

function finishOnlineRace(state,own,other){
 const {winnerId,tied,abandoned}=state.result;
 const won=winnerId===own.id;
 const time=value=>value===null?'—':value.toFixed(2)+'s';
 $('result').dataset.outcome=own.falseStart?'penalty':tied?'tie':won?'win':'loss';
 $('result').dataset.solo='false';
 $('resultMode').textContent='Duelo privado • '+raceDistance+' m';
 $('resultRival').classList.remove('hidden');
 $('resultGap').classList.toggle('hidden',own.time===null||other.time===null);
 $('raceRetry').classList.add('hidden');
 $('resultPlayerCar').textContent=selectedVehicle().chip;
 $('resultRivalCar').textContent=other.name+' · '+rival.model.chip;
 $('resulttime').textContent=time(own.time);
 $('rivalTime').textContent=time(other.time);
 $('raceGap').textContent=own.time!==null&&other.time!==null?time(Math.abs(own.time-other.time)):'—';
 $('resultspd').textContent=own.finishSpeed===null?'—':Math.round(own.finishSpeed);
 $('resultrpm').textContent=own.gear?own.gear+'ª':'N';
 $('resultcash').textContent='+R$ 0';
 $('resultxp').textContent='+0';
 $('resulttitle').textContent=abandoned?'RIVAL SAIU':own.falseStart?'QUEIMA DE LARGADA'
  :tied?'EMPATE':won?'VOCÊ VENCEU!':winnerId?'RIVAL VENCEU':'TEMPO ESGOTADO';
 show('result');
}

function startFreeOnline(){
 if(!data?.vehicleId){show('dealer');return;}
 if(!accounts?.syncFreeDrive||typeof crypto.randomUUID!=='function'){
  toast('O Modo Livre Online precisa de uma conta online e conexão segura.');
  return;
 }
 startGame('free');
 if(!running||mode!=='free')return;
 const model=selectedVehicle();
 laneY=GearLineFreeOnline.spawnLane;
 $('pause').classList.add('hidden');
 $('pauseHelp')?.classList.add('hidden');
 GearLineFreeOnline.loadScenery();
 $('driving').dataset.freeOnline='true';
 $('gametype').textContent='Modo livre • avenida compartilhada';
 $('gametitle').innerHTML='AVENIDA <span style="color:var(--lime)">URBANA.</span>';
 $('modechip').textContent='Conectando à avenida…';
 freeConnection=GearLineFreeOnline.connect(accounts,{
  id:model.id,color:data[model.colorKey]??0,exhaust:Boolean(activeSetup().upgrades.exhaust)
 },()=>({
  dist:car.dist,lane:laneY,speed:paused?0:car.speed,braking:!paused&&brakePressed()
 }),status=>{if($('modechip').textContent!==status)$('modechip').textContent=status;});
}

function startGame(which,raceKind='bot',selectedTrack=selectedRaceTrack(),connection=null){
 if(!data){toast('Entre no perfil antes de dirigir.');return}
 if(!data.vehicleId){show('dealer');return;}
 stopGame();
 onlineRace=connection;
 mode=which==='race'?'race':'free';
 trackId=mode==='race'&&selectedTrack==='dusk'?'dusk':'night';
 raceDistance=raceTracks[trackId].distance;
 $('driving').dataset.mode=mode;
 delete $('driving').dataset.freeOnline;
 car=newRun();
 trafficHitAt=-Infinity;
 freeDrivePaid=0;
 freeDriveSaved=0;
 rival=mode==='race'&&raceKind==='bot'?createRival(activeSetup().upgrades):null;
 $('rivalchip').classList.toggle('hidden',!rival);
 if(rival)$('rivalchip').textContent='Rival: '+rival.model.chip;
 $('raceMap').classList.toggle('hidden',mode!=='race');
 $('raceMap').setAttribute('aria-label',rival?'Mapa da arrancada. Jogador em verde na faixa de baixo, rival em azul na faixa de cima.':'Mapa da arrancada. Jogador em verde.');
 $('mapRival').classList.toggle('hidden',!rival);
 roadScroll=0;raceCameraLead=0;wheelAngle=0;pitch=0;laneY=470;lateral=0;$('steering').classList.toggle('hidden',mode!=='free');countdown=which==='race'?3:0;
 paused=false;
 penalty=false;
 $('pause').textContent='Ⅱ PAUSAR';
 $('pause').classList.toggle('hidden',Boolean(onlineRace));
 $('pauseHelp')?.classList.toggle('hidden',Boolean(onlineRace));
 $('gametype').textContent=mode==='race'?(trackId==='dusk'?'Autódromo ao entardecer':'Reta noturna')+' • '+(rival?'Contra bot':'Contra o relógio'):'Modo livre • condução livre';
 $('gametitle').innerHTML=mode==='race'?'LARGADA <span style="color:var(--lime)">'+raceDistance+' M.</span>':'AVENIDA <span style="color:var(--lime)">NOTURNA.</span>';
 $('carchip').textContent=selectedVehicle().chip;
 $('modechip').textContent=mode==='race'?(rival?'DRAG RACE':'CONTRA O RELÓGIO')+' • '+raceDistance+' M':'FREE DRIVE';
 $('racemsg').textContent=mode==='race'?'PREPARE-SE…':'';
 if(onlineRace){
  $('gametype').textContent='Duelo privado';
  $('modechip').textContent='DUELO PRIVADO • '+raceDistance+' M';
  $('racemsg').textContent='Aguardando rival…';
 }
 $('mobileDisplayStatus').textContent='';
 $('nitrobtn').setAttribute('aria-disabled',String(!activeSetup().upgrades.nitro));
 show('driving');
 startAudio();
 if(window.matchMedia('(pointer:coarse)').matches){
  window.scrollTo(0,0);
  if(document.fullscreenElement!==$('driving'))void toggleDrivingFullscreen();
 }
 if(activeSetup().upgrades.backfire)exhaustEffects.prepareSound(audio);
 running=true;
 last=performance.now();
 renderHud();
 raf=requestAnimationFrame(loop);
}
function dtSafe(){return Math.min(.04,(performance.now()-last)/1000)}
function finishRace(){
 if(!running)return;
 stopGame();
 const gap=rival?car.finishTime-rival.finishTime:null;
 const tied=gap!==null&&Math.abs(gap)<.005;
 const won=gap!==null&&!penalty&&!tied&&gap<0;
 const reward=won?500:0;
 const xp=won?120:0;
 data.races++;
 if(won)data.wins++;
 data.cash+=reward;
 data.xp+=xp;
 data.maxSpeed=Math.max(data.maxSpeed,car.max);
 const record=raceTracks[trackId].record;
 const newRecord=!penalty&&(!data[record]||car.finishTime<data[record]);
 if(newRecord)data[record]=car.finishTime;
 save();
 $('result').dataset.outcome=penalty?'penalty':!rival?'solo':tied?'tie':won?'win':'loss';
 $('result').dataset.solo=String(!rival);
 $('raceRetry').classList.remove('hidden');
 $('resultMode').textContent=(rival?'Arrancada':'Contra o relógio')+' • '+raceDistance+' m';
 $('resultRival').classList.toggle('hidden',!rival);
 $('resultGap').classList.toggle('hidden',!rival);
 $('resultPlayerCar').textContent=selectedVehicle().chip;
 $('resulttime').textContent=car.finishTime.toFixed(2)+'s';
 if(rival){
  $('resultRivalCar').textContent=rival.model.chip+' / '+rival.buildName;
  $('rivalTime').textContent=rival.finishTime.toFixed(2)+'s';
  $('raceGap').textContent=tied?'0.00s':Math.abs(gap).toFixed(2)+'s';
 }
 $('resultspd').textContent=Math.round(car.finishSpeed);
 $('resultcash').textContent='+R$ '+reward;
 $('resultrpm').textContent=car.gear+'ª';
 $('resultxp').textContent='+'+xp;
 $('resulttitle').textContent=penalty?'QUEIMA DE LARGADA'
  :!rival?(newRecord?'NOVO RECORDE!':'LINHA CRUZADA')
  :tied?'EMPATE':won?'VOCÊ VENCEU!':'RIVAL VENCEU';
 show('result');
}
$('raceRetry').onclick=()=>startGame('race',rival?'bot':'clock',trackId);
function canPauseGame(){return running&&!freeConnection&&!onlineRace;}
$('pause').onclick=()=>{if(!canPauseGame())return;paused=!paused;$('pause').textContent=paused?'▶ RETOMAR':'Ⅱ PAUSAR';$('racemsg').textContent=paused?'PAUSADO':'';if(paused){keys={};touch={throttle:false,brake:false}}};
function bindShiftButton(id,direction){
 const button=$(id);
 button.addEventListener('pointerdown',event=>{
  if(event.pointerType==='mouse'&&event.button!==0)return;
  event.preventDefault();
  shift(direction);
 });
 // Keyboard/assistive activation has no pointer click count.
 button.addEventListener('click',event=>{if(event.detail===0)shift(direction)});
}
bindShiftButton('up',1);bindShiftButton('down',-1);
function hold(id,press,release){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);press()});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,release)}
hold('nitrobtn',()=>{
 if(activeSetup().upgrades.nitro)touch.nitro=true;
 else toast('Instale o kit nitro na garagem.');
},()=>touch.nitro=false);
for(const event of ['keydown','keyup']){
 $('nitrobtn').addEventListener(event,e=>{
  if(e.key!==' '&&e.key!=='Enter')return;
  e.preventDefault();
  e.stopPropagation();
  touch.nitro=event==='keydown'&&Boolean(activeSetup()?.upgrades.nitro);
 });
}
hold('throttle',()=>touch.throttle=true,()=>touch.throttle=false);hold('brake',()=>touch.brake=true,()=>touch.brake=false);hold('steerL',()=>keys.a=true,()=>keys.a=false);hold('steerR',()=>keys.d=true,()=>keys.d=false);
window.addEventListener('keydown',e=>{if(typeof e.key!=='string'||!running||e.target?.closest?.('.music-player'))return;let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(e.key.toLowerCase()))e.preventDefault();if(e.key==='Escape'&&running){$('pause').click();return}if((k==='e'||k==='q')&&!e.repeat){shift(k==='e'?1:-1);return}keys[k]=true});window.addEventListener('keyup',e=>{if(typeof e.key==='string')keys[e.key.toLowerCase()]=false});window.addEventListener('blur',()=>{keys={};touch={throttle:false,brake:false};if(document.hidden&&canPauseGame()&&!paused){paused=true;$('pause').textContent='▶ RETOMAR';$('racemsg').textContent='PAUSADO'}})
async function initializeAccount(){
 $('logout').classList.add('hidden');
 $('topuser').textContent='CONTA ONLINE';
 authBusy(true);
 try{
  accounts=createGearLineAccounts();
  const user=await accounts.restore();
  if(accounts.recoveryPending()){
   setAuthMode('reset');
   $('autherr').textContent='Defina sua nova senha para entrar na conta.';
  }else if(user)await openAccount(user);
 }catch(error){
  $('autherr').textContent=authMessage(error);
 }finally{
  authBusy(false); if(!accounts)$('enter').disabled=true;
 }
}
initializeAccount();
